import React from 'react';

import PencilSquare from '@pohodnik/icons/svg/Tools/PencilSquare';

import PageLoader from '@components/PageLoader';
import PohAlert from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';

import { IMedicament } from '../../@types/medicaments.types';
import {
  addMedicamentAsync,
  editMedicamentAsync,
  getMedicamentsAsync,
} from '../../services/medicaments.services';
import { addMedicamentModalAsync, editMedicamentModalAsync } from '../MedicamentModal/modalHelper';

interface IFirstAidKitPageProps {}

const MedicamentsPage: React.FC<IFirstAidKitPageProps> = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IMedicament[]>([]);
  const [err, setErr] = React.useState<string | undefined>(undefined);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const list = await getMedicamentsAsync();
        setData(list);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, []);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert>{err}</PohAlert>;
  }

  const handleAdd = () => {
    addMedicamentModalAsync().then((m) => {
      addMedicamentAsync(m).then((newMedicament) => setData((ms) => [...ms, newMedicament]));
    });
  };

  const handleEdit = (medicamentForEdit: IMedicament) => {
    editMedicamentModalAsync(medicamentForEdit).then((m) => {
      editMedicamentAsync(m).then((updatedMedicament) =>
        setData((ms) => ms.map((m1) => (m1.id === updatedMedicament.id ? updatedMedicament : m1))),
      );
    });
  };

  const groupsMappedData: Record<string, IMedicament[]> = {};

  data.forEach((m) => {
    const k = m.category?.name || 'Без категории';
    if (!groupsMappedData[k]) {
      groupsMappedData[k] = [];
    }
    groupsMappedData[k].push(m);
  });

  return (
    <div>
      <Breadcrumb data={[{ href: '/medicaments', text: 'Медикаменты/Аптечка', active: true }]} />
      <PohContainer>
        <header className="d-flex justify-content-between align-items-center d-print-none">
          <h3 className="mb-3">Медикаменты/Аптечка</h3>
          <PohButton size={ButtonSize.Small} variant={ButtonVariant.Success} onClick={handleAdd}>
            Добавить
          </PohButton>
        </header>

        <table className="table table-border table-condensed table-sm table-striped w-100 table-hover">
          <thead>
            <tr>
              <th>Название</th>
              <th>Форма</th>
              <th>Дозировка</th>
              <th>Применение</th>
              <th>Противопоказания</th>
              <th className="d-print-none">&nbsp;</th>
            </tr>
          </thead>

          {Object.entries(groupsMappedData).map(([groupName, list]) => {
            return (
              <>
                <thead>
                  <tr className="text-info">
                    <th colSpan={8}>{groupName}</th>
                  </tr>
                </thead>
                <tbody>
                  {list.map((m) => (
                    <tr key={m.id}>
                      <td>{m.name}</td>
                      <td>{m.form?.name}</td>
                      <td>{m.dosage}</td>
                      <td>{m.usages}</td>
                      <td>{m.contraindications}</td>
                      <td align="right" className="d-print-none">
                        <PohButton
                          icon={true}
                          onClick={() => handleEdit(m)}
                          variant={ButtonVariant.Light}
                          size={ButtonSize.Small}
                        >
                          <PencilSquare />
                        </PohButton>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </>
            );
          })}
        </table>
      </PohContainer>
    </div>
  );
};

export default MedicamentsPage;
